from pathlib import Path
from html import escape
import json,shutil,zipfile,re
REPO=Path(__file__).resolve().parents[4];ROOT=REPO.parent/'optimizing/shorts';Q=REPO/'docs/project/episodes/shorts-queue.json';queue=json.loads(Q.read_text())
style='''*{box-sizing:border-box}body{margin:0;background:#101114;color:#f5f6f8;font:18px/1.5 Arial,sans-serif}main{max-width:1440px;margin:auto;padding:34px 28px 70px}h1{font-size:clamp(36px,5vw,66px);line-height:1.05;letter-spacing:-.045em}h2{line-height:1.15}p{max-width:850px;color:#bfc7d3}a{color:#b4ceff;text-underline-offset:4px}video{display:block;width:100%;aspect-ratio:16/9;border-radius:16px;background:#202228}.actions{display:flex;gap:16px;flex-wrap:wrap;margin:26px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{background:#1b1e25;border-radius:18px;overflow:hidden}article img{width:100%;display:block}.body{padding:24px}.body p{font-size:16px}button,.button{border:1px solid #4e6284;background:#243449;padding:12px 18px;border-radius:9px;color:#f4f7ff;font:inherit;text-decoration:none;cursor:pointer}a:focus-visible,button:focus-visible{outline:3px solid #caff76;outline-offset:4px}li{margin-bottom:16px}footer{border-top:1px solid #39404b;padding-top:24px;margin-top:45px;color:#aab6c9}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){main{padding:24px 14px}.grid{grid-template-columns:1fr}}'''
def page(title,body,script=''):
 return f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · LinkedIn Beats</title><style>{style}</style><main>{body}<footer>linkedinbeats.com<br>Independent satire. Not affiliated with LinkedIn.<br>A project by Aaron Phelps at Look-Serious.com</footer></main>{script}</html>'
cards=[];downloads=[]
for item in queue['episodes']:
 slug=item['id'];folder=ROOT/slug;out=folder/'output';movie=out/f'{slug}-v1.mp4'
 if not movie.exists():raise SystemExit('Render not ready: '+slug)
 t=json.loads((out/'timeline.json').read_text());briefpath=Q.parent/item['brief'];b=json.loads(briefpath.read_text());seconds=round(t['duration'])
 assert 30<=t['duration']<=40
 item.update(status='review-cut-ready',review_url=f'http://127.0.0.1:8852/shorts/{slug}/',duration_seconds=t['duration'],version=1)
 b.update(status='review-cut-ready',next_step='Review the first short cut for story, voice clarity and restrained performance');briefpath.write_text(json.dumps(b,indent=2,ensure_ascii=False)+'\n')
 shutil.copy2(Q.parent/item['script'],folder/'script.json')
 body=f'''<a href="../">← All five shorts</a> · <a href="/youtube/">Channel art</a><p>Episode {item['episode']} · {seconds} seconds · First review cut</p><h1>{escape(item['title'])}</h1><p>{escape(b['premise'])}</p><video controls playsinline preload="metadata" poster="output/frames/review-2.25.png" src="output/{slug}-v1.mp4"><track kind="captions" srclang="en" label="English" src="output/captions.vtt"></video><div class="actions"><button data-time="0">Intro</button><button data-time="{t['events'][0]['start']}">Meeting</button><button data-time="{t['meetingEnd']}">Afterwards</button></div><div class="actions"><a href="output/{slug}-v1.mp4" download>Download MP4 ↓</a><a href="output/captions.vtt" download>Captions ↓</a><a href="script.json" download>Script ↓</a></div><details><summary>Read the dialogue</summary><ol>{''.join('<li><strong>'+escape(e['who'].capitalize())+'</strong> — '+escape(e['text'])+'</li>' for e in t['events'])}</ol></details><p>1920 × 1080 · 24 fps · Landscape. Original Strategy and Linda voice identities, the established robot voices and 96 BPM score. Filmed human reactions with restrained amplitude-driven mouth animation; first creative review, not phonetic lip sync.</p>'''
 (folder/'index.html').write_text(page(item['title'],body,'''<script>const v=document.querySelector('video');document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.time);v.play().catch(()=>{})});</script>'''))
 cards.append(f'''<article><a href="{slug}/"><img src="{slug}/output/frames/review-2.25.png" alt="{escape(item['title'])}"></a><div class="body"><p>Episode {item['episode']} · {seconds}s</p><h2>{escape(item['title'])}</h2><p>{escape(b['premise'])}</p><a href="{slug}/">Watch this cut ↗</a></div></article>''')
 downloads.extend([(movie,f'{slug}/{movie.name}'),(out/'captions.vtt',f'{slug}/captions.vtt'),(folder/'script.json',f'{slug}/script.json')])
queue['status']='review-cuts-ready';Q.write_text(json.dumps(queue,indent=2,ensure_ascii=False)+'\n')
(ROOT/'index.html').write_text(page('Five quick meetings','''<a href="/series/">← Previous meetings</a> · <a href="/youtube/">YouTube channel kit</a><p>LinkedIn Beats · Episodes 05–09</p><h1>Five quick meetings.</h1><p>Strategy has a framework. Linda has the file. Corporate has brought a banner.</p><p>Five first cuts, each 31–34 seconds. Same dry performances, original voices, paper collage and music. Three visits from Corporate, with Synthia as the training liaison.</p><div class="actions"><a class="button" href="linkedinbeats-five-shorts.zip" download>Download all five MP4s + captions ↓</a></div><div class="grid">'''+''.join(cards)+'</div>'))
with zipfile.ZipFile(ROOT/'linkedinbeats-five-shorts.zip','w',zipfile.ZIP_DEFLATED,compresslevel=3) as z:
 for src,name in downloads:z.write(src,name)
 z.writestr('START-HERE.txt','Five first review cuts. Landscape 1920x1080, 24 fps, 31–34 seconds. No account uploads performed.\nReview: http://127.0.0.1:8852/shorts/\n')
# Add the new collection to the existing local entry points without replacing older films.
for rel in ['series/index.html','paper-meeting-chatgpt/studio/index.html','youtube/index.html']:
 p=ROOT.parent/rel;s=p.read_text();s=re.sub(r'<aside id="new-shorts">.*?</aside>','',s,flags=re.S);s=s.replace('<main>','<main><aside id="new-shorts"><p><a href="/shorts/">New: five 30–40 second meetings with Strategy, Linda and Corporate ↗</a></p></aside>',1);p.write_text(s)
print('Five review pages, collection hub and portable video ZIP ready.')
